import numpy as np
from collections import Counter
H,W=inp.shape
def nb4(r,c):
    return [(r+dr,c+dc) for dr,dc in((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<H and 0<=c+dc<W]
def nb8(r,c):
    return [(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0) and 0<=r+dr<H and 0<=c+dc<W]
for name,f in(("4nb",nb4),("8nb",nb8)):
    cnt={4:Counter(),3:Counter()}
    for r in range(H):
        for c in range(W):
            if inp[r,c]==4:
                k=sum(1 for rr,cc in f(r,c) if inp[rr,cc]==2)
                cnt[out[r,c]][k]+=1
    print(name, "stay4:",dict(cnt[4]), "become3:",dict(cnt[3]))

