                np.minimum(np.arange(W)[None,:], (W-1-np.arange(W))[None,:]))  # dist to border
for name, D in (("d2",d2),("db",db)):
    cnt={4:Counter(),3:Counter()}
    for r in range(H):
        for c in range(W):
            if inp[r,c]==4: cnt[out[r,c]][D[r,c]]+=1
    print(name,"stay4:",dict(sorted(cnt[4].items())),"become3:",dict(sorted(cnt[3].items())))

stay=(inp==4)&(out==4)
