                    else:
                        k=sum(inp[max(0,r-rad):r+rad+1, max(0,c-rad):c+rad+1].astype(bool).ravel()) if False else sum(1 for rr in range(H) for cc in range(W) if abs(rr-r)+abs(cc-c)<=rad and inp[rr,cc]==2)
                    cnt[out[r,c]][k]+=1
        # check separability
        stayks=set(cnt[4]); becomeks=set(cnt[3])
        sep = stayks.isdisjoint(becomeks)
        print(rad, metric, "stay:",dict(sorted(cnt[4].items())), "become:",dict(sorted(cnt[3].items())), "SEP" if sep else "")

cnt={4:Counter(),3:Counter()}
for r in range(H):
    for c in range(W):
        if inp[r,c]==4:
            row2=sum(1 for cc in range(W) if inp[r,cc]==2)
            col2=sum(1 for rr in range(H) if inp[rr,c]==2)
            d1=sum(1 for k in range(-30,30) if 0<=r+k<H and 0<=c+k<W and inp[r+k,c+k]==2)
            d2_=sum(1 for k in range(-30,30) if 0<=r+k<H and 0<=c-k<W and inp[r+k,c-k]==2)
