from scipy import ndimage
from collections import Counter
def comp_check(inp,out,bg):
    H,W=inp.shape
    lab,n=ndimage.label(inp==bg)  # 4-conn through background
    st={}
    for r in range(H):
        for c in range(W):
            if inp[r,c]==bg:
                v=out[r,c]
                st.setdefault(lab[r,c],set()).add(v)
    return n, {k:sorted(v) for k,v in sorted(st.items())}
n,s=comp_check(i2,o2,5)
print("demo2 comps:",n)
for k,v in s.items(): print(k,v)
n1,s1=comp_check(inp,out,4)
print("demo1 comps:",n1)
for k,v in s1.items(): print(k,v)

st8=ndimage.generate_binary_structure(2,2)
def comp8(inp,out,bg):
    H,W=inp.shape
    lab,n=ndimage.label(inp==bg, structure=st8)
    st={}
    for r in range(H):
        for c in range(W):
            if inp[r,c]==bg: st.setdefault(lab[r,c],Counter())[out[r,c]]+=1
    return n, {k:dict(v) for k,v in sorted(st.items())}
